# ---------- projection initialisation errors ----------
class ProjInitError(Exception):
    def __init__(self, code, category, detail=None):
        self.code = code
        self.category = category
        self.detail = detail
    def prefix(self):
        if self.code is None:
            return "proj_create: unrecognized format / unknown name\n"
        if self.detail:
            return f"proj_create: Error {self.code} ({self.category}): {self.detail}\n"
        else:
            return f"proj_create: Error {self.code} ({self.category})\n"
    def cause(self):
        if self.code is None:
            return "Unknown error (code 2)"
        return self.category

def init_error(code, category, detail):
    return ProjInitError(code, category, detail)

MISSING = "Missing argument"
INVALID = "Invalid value for an argument"
MUTUAL = "Mutually exclusive arguments"
SYNTAX = "Invalid PROJ string syntax"

# ---------- parameters ----------
class Params:
    def __init__(self, pairs):
        # pairs: list of (key, value_or_None) in order; first wins
        self.pairs = pairs
        self.map = {}
        for k, v in pairs:
            if k not in self.map:
                self.map[k] = v
    def has(self, k):
        return k in self.map
    def get(self, k, default=None):
        v = self.map.get(k, default)
        return v
    def get_str(self, k, default=None):
        v = self.map.get(k, None)
        if v is None:
            return default
        return v
    def get_float(self, k, default=0.0):
        v = self.map.get(k, None)
        if v is None:
            return default
        val, _ = c_strtod(v)
        return val
    def get_angle(self, k, default=0.0):
        """Return radians. Angular params are given in degrees (DMS allowed)."""
        v = self.map.get(k, None)
        if v is None:
            return default
        deg, _ = dmstor(v)
        return math.radians(deg)
    def get_bool(self, k):
        return k in self.map

def parse_params_from_tokens(tokens):
    pairs = []
    for tok in tokens:
        # tok includes leading '+' for proj-mode tokens; for pipeline steps etc
        s = tok[1:] if tok.startswith('+') else tok
        if s == '':
            continue
        if '=' in s:
            k, v = s.split('=', 1)
        else:
            k, v = s, None
        pairs.append((k, v))
    return Params(pairs)

def parse_params_from_string(s):
    pairs = []
    for tok in s.split():
        t = tok[1:] if tok.startswith('+') else tok
        if t == '':
            continue
        if '=' in t:
            k, v = t.split('=', 1)
        else:
            k, v = t, None
        pairs.append((k, v))
    return Params(pairs)

# ---------- ellipsoid ----------
class Ellipsoid:
    def __init__(self, a, b):
        self.a = a
        self.b = b
        if a and b:
            self.f = (a-b)/a
            self.rf = 1.0/self.f if self.f != 0 else 0.0
            self.es = 1.0 - (b/a)**2
            self.e = math.sqrt(self.es) if self.es > 0 else 0.0
        else:
            self.f = 0.0; self.rf = 0.0; self.es = 0.0; self.e = 0.0
        self.one_es = 1.0 - self.es
        # meridional arc coefficients (PROJ pj_mlfn)
        es = self.es
        self.en = []
        if es != 0:
            # coefficients from PROJ (Snyder) for mlfn
            self.en = [
                1.0 - es*(0.25 + es*(3.0/64.0 + es*(5.0/256.0))),
                # filled by mlfn setup below
            ]
        # Precompute en as in PROJ: en[0..4]
        e1 = es
        self.mlfn_en = [
            1.0 - e1*(1.0/4.0 + e1*(3.0/64.0 + e1*(5.0/256.0))),
            e1*(3.0/4.0 + e1*(3.0/8.0 + e1*(15.0/512.0))),
            e1*e1*(15.0/256.0 + e1*(45.0/1024.0)),
            e1*e1*e1*(35.0/3072.0),
            e1*e1*e1*e1*(315.0/131072.0),
        ] if False else None
        # Use standard PROJ en calculation:
        en = []
        es_ = es
        # pj_enfn
        C00 = 1.0
        C02 = 0.25
        C04 = 0.046875
        C06 = 0.01953125
        C08 = 0.01068115234375
        C22 = 0.75
        C44 = 0.46875
        C46 = 0.013020833333333333
        C48 = 0.007120768229166667
        C66 = 0.3645833333333333
        C68 = 0.005696614583333333
        C88 = 0.3076171875
        # PROJ pj_enfn:
        en.append(C00 - es_*(C02 + es_*(C04 + es_*(C06 + es_*C08))))
        en.append(es_*(C22 - es_*(C04 + es_*(C06 + es_*C08))))
        en.append(es_**2*(C44 - es_*(C46 + es_*C48)))
        en.append(es_**3*(C66 - es_*C68))
        en.append(es_**4*C88)
        self.en = en

    def mlfn(self, phi, sphi, cphi):
        """Meridional distance from equator (PROJ pj_mlfn)."""
        en = self.en
        # PROJ uses: cphi * phi - ... series in sin(2phi)...
        return (en[0]*phi - cphi*(en[1] + sphi*(en[2] + sphi*(en[3] + sphi*en[4])))*sphi) * 1.0 if False else \
               (en[0]*phi - cphi*sphi*(en[1] + sphi*sphi*(en[2] + sphi*sphi*(en[3] + sphi*sphi*en[4]))))
    def inv_mlfn(self, y_over_a):
        """Inverse meridional arc: y is mlfn value (already divided by a*k0 etc handled by caller as phi approx)"""
        # caller passes (distance / a) scaled such that mlfn(phi) ~= that
        phi = y_over_a / self.en[0] if self.en and self.en[0] else y_over_a
        es = self.es
        if es == 0:
            return phi
        for _ in range(12):
            s = math.sin(phi); c = math.cos(phi)
            f = self.mlfn(phi, s, c) - y_over_a
            # derivative: (1-es?) Approx using formula: d(mlfn)/dphi = (1-es) / (1-es sin^2)^(3/2) ??? 
            # PROJ uses Newton with derivative: 1/sqrt(1-es sin^2) * ??? Use numeric-safe analytic:
            d = (1.0 - es) / ((1.0 - es*s*s)**1.5) if False else math.sqrt(1-es*s*s)  # placeholder refined below
            # Actually mlfn as defined (with a=1) derivative = (1-es) / (1-es*sin^2)^(3/2) *? Let's compute numeric derivative
            h = 1e-7
            d_num = (self.mlfn(phi+h, math.sin(phi+h), math.cos(phi+h)) - self.mlfn(phi-h, math.sin(phi-h), math.cos(phi-h))) / (2*h)
            if d_num == 0:
                break
            delta = f / d_num
            phi -= delta
            if abs(delta) < 1e-14:
                break
        return phi

def setup_ellipsoid(params):
    """Return Ellipsoid or raise ProjInitError."""
    # datum validation first (unknown datum is an error even if a given)
    datum = params.get_str('datum', None)
    datum_ell = None
    if datum is not None:
        if datum not in DATUMS:
            raise init_error(1027, INVALID, "Unknown value for datum")
        datum_ell = DATUMS[datum]
    # base
    a = None; b = None
    specified_invalid = False
    specified_any = False  # parameters that count as specifying (a/R/ellps/datum)
    ellps_name = params.get_str('ellps', None)
    base_found = False
    if ellps_name is not None:
        specified_any = True
        if ellps_name in ELLPS:
            a, b, rf_, _desc = ELLPS[ellps_name]
            base_found = True
        else:
            specified_invalid = True
    elif datum_ell is not None:
        specified_any = True
        if datum_ell in ELLPS:
            a, b, rf_, _desc = ELLPS[datum_ell]
            base_found = True
    # R
    if params.has('R'):
        specified_any = True
        Rv, _ = c_strtod(params.get_str('R', ''))
        if Rv > 0:
            a = Rv; b = Rv; base_found = True
        else:
            specified_invalid = True
    if params.has('a'):
        specified_any = True
        av, _ = c_strtod(params.get_str('a', ''))
        if av > 0:
            a = av
            if not base_found or params.has('R') or ellps_name is None and datum_ell is None:
                # a alone resets to sphere unless ellipsoid base with overrides later
                # If ellps/datum supplied, b stays from base for now (overrides below may change)
                if ellps_name is None and datum_ell is None:
                    b = av
            base_found = True
        else:
            specified_invalid = True
    if not base_found:
        # default GRS80 unless no_defs
        if not specified_any and not params.has('no_defs'):
            a, b, rf_, _d = ELLPS.get('GRS80', (6378137.0, 6356752.314140, 298.257222101, ''))
            base_found = True
        else:
            if specified_invalid or ellps_name is not None or params.has('a') or params.has('R'):
                raise init_error(1027, INVALID, "pj_init_ctx: Must specify ellipsoid or sphere")
            else:
                raise init_error(1026, MISSING, "pj_init_ctx: Must specify ellipsoid or sphere")
    # Overrides for shape, in PROJ-like precedence: b, rf, f, e, es handled
    # We examine presence; PROJ applies (roughly) last-computed from these.
    # Test-driven precedence: explicit b after ellps overrides; rf after ellps overrides.
    # Apply in order b -> rf -> f -> e -> es if present (each recomputes b).
    shape_invalid = False
    if params.has('b'):
        bv, _ = c_strtod(params.get_str('b', ''))
        b = bv
        if bv <= 0 or bv is None:
            shape_invalid = True
    if params.has('rf'):
        rv, _ = c_strtod(params.get_str('rf', ''))
        if rv > 1:  # rf must be >? rf=1 gives b=0 invalid, rf=0 invalid
            b = a * (1.0 - 1.0/rv)
        elif rv == 0 or rv <= 1:
            # rf=1 -> b=0 invalid below
            if rv == 1:
                b = 0.0
            else:
                shape_invalid = True
    if params.has('f'):
        fv, _ = c_strtod(params.get_str('f', ''))
        b = a * (1.0 - fv)
        if fv >= 1 or fv < 0 and False:
            pass
    if params.has('e'):
        ev, _ = c_strtod(params.get_str('e', ''))
        if abs(ev) < 1:
            b = a * math.sqrt(max(0.0, 1-ev*ev))
        else:
            shape_invalid = True
    if params.has('es'):
        esv, _ = c_strtod(params.get_str('es', ''))
        if esv < 1:
            b = a * math.sqrt(max(0.0, 1-esv))
        else:
            shape_invalid = True
    if a is None or b is None or a <= 0 or b <= 0 or b > a*1.0000001:
        # f=2 case: b negative -> invalid
        raise init_error(1027, INVALID, "pj_init_ctx: Must specify ellipsoid or sphere")
    if shape_invalid:
        raise init_error(1027, INVALID, "pj_init_ctx: Must specify ellipsoid or sphere")
    # f>=1 etc: b<=0 caught above. f negative gives b>a -> caught as b>a
    return Ellipsoid(a, b)

PY"}

