# ---------- common math helpers ----------
def auth_lat(phi, es):
    """Authalic latitude (PROJ pj_authlat)."""
    if es == 0:
        return phi
    # PROJ uses APA coefficients
    e2 = es
    # apa[0]= e2*(1/3 + e2*(31/180 + e2*517/5040)) etc from memory:
    # Use series: auth = phi - (es/3 + 31 es^2/180+...) sin2phi ...
    # Compute via coefficients used in PROJ pj_authfn:
    t = es
    apa0 = t*(1.0/3.0 + t*(31.0/180.0 + t*(517.0/5040.0)))
    apa1 = t*t*(23.0/360.0 + t*(251.0/3780.0))
    apa2 = t*t*t*(761.0/45360.0)
    return phi - apa0*math.sin(2*phi) - apa1*math.sin(4*phi) - apa2*math.sin(6*phi) if False else \
        phi + (-apa0)*math.sin(2*phi)  # placeholder replaced below

# Correct authalic implementations (defined cleanly)
def pj_authfn(es):
    t = es
    return [
        t*(1.0/3.0 + t*(31.0/180.0 + t*(517.0/5040.0))),
        t*t*(23.0/360.0 + t*(251.0/3780.0)),
        t*t*t*(761.0/45360.0),
    ]
def authlat(phi, apa):
    # PROJ: return phi + apa[0]*sin(2phi)+... with apa signs? pj_authlat:
    #   return (phi + apa[0] * sin(2phi) ...) where apa computed with negative? Check numeric later.
    return phi - apa[0]*math.sin(2*phi) - apa[1]*math.sin(4*phi) - apa[2]*math.sin(6*phi) if False else phi + apa[0]*math.sin(2*phi) + apa[1]*math.sin(4*phi) + apa[2]*math.sin(6*phi)

def tsfn(phi, sphi, e):
    """PROJ pj_tsfn: conformal latitude factor."""
    if e == 0:
        return math.tan(math.pi/4 - phi/2) if False else math.tan(0.25*math.pi + 0.5*phi) ** -1 if False else _tsfn_s(phi)
    # pj_tsfn(phi, sinphi, e) = tan(pi/4 - phi/2) / ((1-e sin)/(1+e sin))^(e/2) ??? sign conventions vary.
    return _tsfn_e(phi, sphi, e)

def _tsfn_s(phi):
    # value t such that merc y = -a*log(t) for spherical
    return math.tan(math.pi/4.0 - phi/2.0)
def _tsfn_e(phi, sphi, e):
    c = e * sphi
    return math.tan(math.pi/4.0 - phi/2.0) / (((1.0-c)/(1.0+c)) ** (e/2.0))

def msfn(sphi, cphi, es):
    """PROJ pj_msfn."""
    return cphi / math.sqrt(1.0 - es*sphi*sphi)

def phi2(ts, e):
    """Inverse conformal latitude (PROJ pj_phi2)."""
    if e == 0:
        return math.pi/2 - 2*math.atan(ts)
    eccnth = 0.5*e
    phi = math.pi/2 - 2*math.atan(ts)
    for _ in range(15):
        con = e*math.sin(phi)
        dphi = math.pi/2 - 2*math.atan(ts * (((1-con)/(1+con)) ** eccnth)) - phi
        phi += dphi
        if abs(dphi) < 1e-14:
            break
    return phi

def adjust_lon(lam):
    """Wrap to [-pi, pi]."""
    if abs(lam) <= math.pi:
        return lam
    lam = math.fmod(lam, 2*math.pi)
    if lam > math.pi:
        lam -= 2*math.pi
    elif lam < -math.pi:
        lam += 2*math.pi
    return lam

def adjlon(lam):
    return adjust_lon(lam)

