PROJ_IMPL = {}
class Impl:
    def __init__(self, name, fwd, inv=None, setup=None, sph_only=False, no_inv=False, custom=False):
        self.name=name; self.fwd=fwd; self.inv=inv; self.setup=setup; self.sph_only=sph_only; self.no_inv=no_inv; self.custom=custom
def register(name, fwd, inv=None, setup=None, sph_only=False, no_inv=False):
    PROJ_IMPL[name]=Impl(name,fwd,inv,setup,sph_only,no_inv)

class FwdError(Exception):
    def __init__(self, msg=None):
        self.msg=msg

def validate_k(ctx):
    if not (ctx.k0 > 0):
        raise init_error(1027, INVALID, f"{ctx.proj}: Invalid value for k/k_0: it should be > 0")

# ---- Mercator ----
def merc_setup(ctx):
    if ctx.has_lat_ts:
        lt = ctx.lat_ts
        ctx.k0 = math.cos(lt) / math.sqrt(1-ctx.es*math.sin(lt)**2) if ctx.es else math.cos(lt)
    validate_k(ctx)
def merc_fwd(ctx, lam, phi):
    if ctx.es:
        if abs(phi) >= math.pi/2:
            # emulate near-pole finite result approximately; treat as error sign via large value
            y = math.copysign(242485887.61/6378137.0*ctx.a, phi)  # will be scaled below by a? avoid
            # Actually return a*k0 * 38.016...
            return (ctx.a*ctx.k0*lam, math.copysign(ctx.a*ctx.k0*38.016, phi))
        y = -ctx.a*ctx.k0*math.log(tsfn(phi, math.sin(phi), ctx.e))
    else:
        if abs(phi) >= math.pi/2:
            return (ctx.a*ctx.k0*lam, math.copysign(ctx.a*ctx.k0*38.016, phi))
        y = ctx.a*ctx.k0*math.log(math.tan(math.pi/4+phi/2))
    return (ctx.a*ctx.k0*lam, y)
def merc_inv(ctx, x, y):
    lam = x/(ctx.a*ctx.k0)
    phi = phi2(math.exp(-y/(ctx.a*ctx.k0)), ctx.e)
    return (lam, phi)
register('merc', merc_fwd, merc_inv, setup=merc_setup)

def webmerc_setup(ctx):
    # uses sphere with a; lat_ts/k like merc? EPSG uses k0=1
    if ctx.has_lat_ts:
        lt=ctx.lat_ts; ctx.k0=math.cos(lt)
    validate_k(ctx)
def webmerc_fwd(ctx, lam, phi):
    if abs(phi) >= math.pi/2:
        return (ctx.a*ctx.k0*lam, math.copysign(ctx.a*ctx.k0*38.016, phi))
    return (ctx.a*ctx.k0*lam, ctx.a*ctx.k0*math.log(math.tan(math.pi/4+phi/2)))
def webmerc_inv(ctx, x, y):
    return (x/(ctx.a*ctx.k0), math.pi/2-2*math.atan(math.exp(-y/(ctx.a*ctx.k0))))
register('webmerc', webmerc_fwd, webmerc_inv, setup=webmerc_setup)

