def c_format(fmt, value):
    """Format like C printf; return string or None if Wrong formatString."""
    # parse fmt
    m = re.match(r'^%(\+)?(0*)([0-9]*)(?:\.([0-9]*))?([fFeEgG])$', fmt)
    if not m:
        err_write(f"Wrong formatString '{fmt}'\n")
        return ""
    width_s = m.group(3); prec_s = m.group(4)
    try:
        width = int(width_s) if width_s else 0
        prec = int(prec_s) if prec_s not in (None, '') else (0 if prec_s == '' else 6)
        # default precisions per conversion
        if prec_s is None:
            prec = 6
    except Exception:
        err_write(f"Wrong formatString '{fmt}'\n"); return ""
    if width > 1000 or (prec_s not in (None,) and prec > 1000):
        err_write(f"Wrong formatString '{fmt}'\n"); return ""
    # Python's % operator implements C-like formatting for float.
    try:
        # Normalize fmt for Python: Python accepts %0... etc and %.f (prec empty?) Python %.f works as .0f
        return fmt % value
