def wintri_fwd(ctx, lam, phi):
    alpha, sinc = aitoff_aux(lam,phi)
    cosphi1=2/math.pi
    if alpha==0:
        x=ctx.a*ctx.k0*lam*cosphi1; y=ctx.a*ctx.k0*phi
        # average formulas reduce to ?
        return (x,y)
    xait=2*math.cos(phi)*math.sin(lam/2)/sinc
    # Winkel uses aitoff term as lam*cosphi/sinc? Use expression that for small lam matches aitoff x/ ? 
    # Standard Winkel Tripel (Snyder): x = (a/2) lam [cosphi1 + (cosphi * sin(lam/2)/(lam/2))/sinc ???]
    # Our xait above /(?) For averaging we need aitoff in same lam scale: xait_scaled = (2 sin(lam/2) cosphi / sinc)
    # But earlier derivation used aitoff x = that. eqc x = lam*cosphi1. Average:
    x=ctx.a*ctx.k0*0.5*(lam*cosphi1 + xait)
    y=ctx.a*ctx.k0*0.5*(phi + math.sin(phi)/sinc)
    return (x,y)
