# ---------- Mollweide ----------
def moll_fwd(ctx, lam, phi):
    # solve 2t+sin2t = pi sin phi
    sp=math.sin(phi)
    # Newton
    theta=phi
    for _ in range(20):
        f=2*theta+math.sin(2*theta)-math.pi*sp
        d=2+2*math.cos(2*theta)
        if d==0: break
        delta=f/d; theta-=delta
        if abs(delta)<1e-14: break
    x=ctx.a*ctx.k0*(2*math.sqrt(2)/math.pi)*lam*math.cos(theta)
    y=ctx.a*ctx.k0*math.sqrt(2)*math.sin(theta)
    return (x,y)
register('moll', moll_fwd, None, setup=validate_k, sph_only=True)

# ---------- Robinson ----------
ROBIN_TABLE=[
(0,1.0000,0.0000),(5,0.9986,0.0620),(10,0.9954,0.1240),(15,0.9900,0.1860),(20,0.9822,0.2480),
(25,0.9730,0.3100),(30,0.9600,0.3720),(35,0.9427,0.4340),(40,0.9216,0.4958),(45,0.8962,0.5571),
(50,0.8679,0.6176),(55,0.8350,0.6769),(60,0.7986,0.7346),(65,0.7597,0.7903),(70,0.7186,0.8435),
(75,0.6732,0.8936),(80,0.6213,0.9394),(85,0.5722,0.9761),(90,0.5322,1.0000)]
def robin_interp(phi_deg):
    ad=abs(phi_deg)
    if ad>=90: return ROBIN_TABLE[-1][1], ROBIN_TABLE[-1][2]
    idx=int(ad//5)
    t=(ad-idx*5)/5.0
    # cubic Lagrange using points idx-1..idx+2 (clamped indices for evaluation via linear fallback at edges?)
    # Use PROJ-like interpolation: we'll initially use cubic interpolation over surrounding nodes.
    def interp(comp):
        pts=[]
        for k in range(idx-1, idx+3):
            kk=max(0,min(len(ROBIN_TABLE)-1,k))
            pts.append((k*5, ROBIN_TABLE[kk][comp]))
        # If clamped duplicates, fall back linear
        if len(set(p[0] for p in pts))<4:
            x0,y0=ROBIN_TABLE[idx][0],ROBIN_TABLE[idx][comp]
            x1,y1=ROBIN_TABLE[idx+1][0],ROBIN_TABLE[idx+1][comp]
            return y0+(y1-y0)*t
        # Lagrange at ad
        res=0.0
        for ii,(xi, yi) in enumerate(pts):
            term=yi
            for jj,(xj,_) in enumerate(pts):
                if ii!=jj:
                    term*= (ad-xj)/(xi-xj)
            res+=term
        return res
    return interp(1), interp(2)
def robin_fwd(ctx, lam, phi):
    fx, fy = robin_interp(math.degrees(phi))
    x=ctx.a*ctx.k0*0.8487*lam*fx
    y=ctx.a*ctx.k0*1.3523*fy
    if phi<0: y=-y
    return (x,y)
