# ---------- Azimuthal spherical helpers ----------
def azi_sph_fwd(ctx, lam, phi, mode):
    phi1=ctx.lat0; sp1=math.sin(phi1); cp1=math.cos(phi1)
    sp=math.sin(phi); cp=math.cos(phi)
    coslam=math.cos(lam)
    if mode=='ortho':
        cosc=sp1*sp+cp1*cp*coslam
        if cosc<0: raise FwdError()
        x=ctx.a*ctx.k0*cp*math.sin(lam)
        y=ctx.a*ctx.k0*(cp1*sp-sp1*cp*coslam)
        return (x,y)
    if mode=='gnom':
        cosc=sp1*sp+cp1*cp*coslam
        if cosc<=0: raise FwdError()
        k=1/cosc
        x=ctx.a*ctx.k0*k*cp*math.sin(lam)
        y=ctx.a*ctx.k0*k*(cp1*sp-sp1*cp*coslam)
        return (x,y)
    if mode=='stere':
        denom=1+sp1*sp+cp1*cp*coslam
        if denom<=1e-15: raise FwdError()
        k=2*ctx.k0/denom
        # lat_ts handling is in setup altering k0; here k includes
        x=ctx.a*k*cp*math.sin(lam)
        y=ctx.a*k*(cp1*sp-sp1*cp*coslam)
        return (x,y)
    if mode=='laea':
        denom=1+sp1*sp+cp1*cp*coslam
        if denom<=0: raise FwdError()
        k=math.sqrt(2/denom)
        x=ctx.a*ctx.k0*k*cp*math.sin(lam)
        y=ctx.a*ctx.k0*k*(cp1*sp-sp1*cp*coslam)
        return (x,y)
    if mode=='aeqd':
        cosc=sp1*sp+cp1*cp*coslam
        cosc=max(-1,min(1,cosc)); c=math.acos(cosc)
        if c<1e-12:
            return (0.0,0.0)
        k=c/math.sin(c)
        x=ctx.a*ctx.k0*k*cp*math.sin(lam)
        y=ctx.a*ctx.k0*k*(cp1*sp-sp1*cp*coslam)
        return (x,y)
    raise FwdError()

