    p=ctx.params
    if not p.has('lat_1') and not p.has('lat_2'):
        raise init_error(1027, INVALID, "lcc: Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0")
    lat1=ctx.lat1
    lat2=ctx.lat2 if p.has('lat_2') else lat1
    ctx._lat1_eff=lat1; ctx._lat2_eff=lat2
    if abs(lat1+lat2)==0:
        raise init_error(1027, INVALID, "lcc: Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0")
