# ---------- Albers ----------
def aea_setup(ctx):
    p=ctx.params
    if not p.has('lat_1') and not p.has('lat_2'):
        raise init_error(1027, INVALID, "aea: Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0")
    lat1=ctx.lat1; lat2=ctx.lat2 if p.has('lat_2') else lat1
    ctx._lat1_eff=lat1; ctx._lat2_eff=lat2
    if abs(lat1+lat2)==0:
        raise init_error(1027, INVALID, "aea: Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0")
    validate_k(ctx)
    es=ctx.es
    def m(phi): return msfn(math.sin(phi), math.cos(phi), es)
    def q(phi): return qsfn(ctx, math.sin(phi)) if es else 2*math.sin(phi)
    m1,m2=m(lat1),m(lat2); q1,q2=q(lat1),q(lat2)
    if lat1!=lat2:
        if q2==q1: n=math.sin(lat1)
        else: n=(m1*m1-m2*m2)/(q2-q1)
    else:
        n=math.sin(lat1)
    ctx._aea_n=n
    ctx._aea_C=m1*m1+n*q1
    ctx._aea_q=q
    q0=q(ctx.lat0)
    ctx._aea_rho0=ctx.a*math.sqrt(max(0.0,ctx._aea_C-n*q0))/n if n!=0 else 0.0
