    n=ctx._aea_n; q=ctx._aea_q(phi)
    val=ctx._aea_C-n*q
    if val<0: raise FwdError()
    rho=ctx.a*math.sqrt(val)/n if n!=0 else 0.0
    theta=n*lam
    return (ctx.k0*rho*math.sin(theta), ctx.k0*(ctx._aea_rho0-rho*math.cos(theta)))
def aea_inv(ctx,x,y):
    return numeric_inv(ctx,x,y,aea_fwd)
register('aea', aea_fwd, aea_inv, setup=aea_setup)

