        raise init_error(1027, INVALID, "eqdc: Invalid value for lat_1 and lat_2: |lat_1 + lat_2| should be > 0")
    validate_k(ctx)
    es=ctx.es
    def m(phi): return msfn(math.sin(phi), math.cos(phi), es)
