    return math.pi/2-2*math.atan(math.tan(math.pi/4-phi/2)/(((1-e*math.sin(phi))/(1+e*math.sin(phi)))**(e/2)))
def sph_stere(lam,phi,phi1):
    chi1=chi(phi1); c=chi(phi)
    den=1+math.sin(chi1)*math.sin(c)+math.cos(chi1)*math.cos(c)*math.cos(lam)
