    res=[]
    for l in out:
        if '*' in l: res.append((None,None))
        else: res.append(tuple(map(float,l.split())))
    return res

def transform(phi,kind):
    if kind=='geod': return phi
    if kind=='conf': return math.pi/2-2*math.atan(math.tan(math.pi/4-phi/2)/(((1-e*math.sin(phi))/(1+e*math.sin(phi)))**(e/2)))
    if kind=='auth':
        # sin beta = qsfn/qp
        def q(s):
            return (1-es)*(s/(1-es*s*s)-(1/(2*e))*math.log((1-e*s)/(1+e*s))) if e else 2*s
        return math.asin(max(-1,min(1,q(math.sin(phi))/q(1.0))))
    if kind=='geoc': return math.atan((1-es)*math.tan(phi))
    if kind=='rect': return math.asin(math.sin(phi)) # placeholder

