    if mode=='ortho':
        if sp1*sp+cp1*cp*cl <0: return (None,None)
        return (a*cp*math.sin(lam), a*(cp1*sp-sp1*cp*cl))
    if mode=='gnom':
        c=sp1*sp+cp1*cp*cl
        if c<=0: return (None,None)
        return (a*cp*math.sin(lam)/c, a*(cp1*sp-sp1*cp*cl)/c)
    if mode=='aeqd':
        c=math.acos(max(-1,min(1,sp1*sp+cp1*cp*cl)))
        if c<1e-12: return (0,0)
        k=c/math.sin(c); return (a*k*cp*math.sin(lam), a*k*(cp1*sp-sp1*cp*cl))
    if mode=='stere':
        den=1+sp1*sp+cp1*cp*cl; k=2/den; return (a*k*cp*math.sin(lam), a*k*(cp1*sp-sp1*cp*cl))

