# ---------- Stereographic ellipsoidal (conformal sphere + centre scale) ----------
def conf_lat(phi, e, es):
    if e == 0:
        return phi
    return phi2(tsfn(phi, math.sin(phi), e), e) if False else (math.pi/2 - 2*math.atan(tsfn(phi, math.sin(phi), e)))
def stere_setup2(ctx):
    validate_k(ctx)
    ctx._stere_corr = 1.0
    if ctx.es:
        phi0 = ctx.lat0
        # centre scale of conformal-sphere method
        h=1e-6
        dchi = (conf_lat(phi0+h, ctx.e, ctx.es)-conf_lat(phi0-h, ctx.e, ctx.es))/(2*h) if abs(abs(phi0)-math.pi/2)>1e-9 else None
        if dchi is None:
            # pole limit: dchi/dphi at pole = 1/sqrt(1-es)
            dchi = 1.0/math.sqrt(1-ctx.es)
            M0 = ctx.a/math.sqrt(1-ctx.es)
        else:
            M0 = ctx.a*(1-ctx.es)/((1-ctx.es*math.sin(phi0)**2)**1.5)
        if abs(abs(phi0)-math.pi/2) < 1e-9:
            M0 = ctx.a/math.sqrt(1-ctx.es)
        sc = ctx.a*dchi/M0 if M0 else 1.0
        ctx._stere_corr = 1.0/sc if sc else 1.0
        # polar lat_ts correction
        if abs(abs(phi0)-math.pi/2) < 1e-9 and ctx.has_lat_ts:
            # base scale at lat_ts (without k0/corr?) Our base method at pole has corr as above,
            # which at pole is 1. Compute scale of base (radius a conformal sphere) at phi_ts.
            sign = 1 if phi0>0 else -1
            phi_ts = sign*abs(ctx.lat_ts)
            chi_ts = conf_lat(phi_ts, ctx.e, ctx.es)
            # projected radial distance from pole for a point at phi_ts (lam=0)
            # Using spherical stere centred at pole: rho = 2a * tan((pi/2 - sign*chi_ts)/2?) for north: distance = 2a*tan((pi-chi)/2?) 
            if sign>0:
                rho = 2*ctx.a*math.tan((math.pi/2-chi_ts)/2) if False else 2*ctx.a*math.tan(math.pi/4-chi_ts/2)
            else:
                rho = 2*ctx.a*math.tan(math.pi/4+chi_ts/2)
            Nts = ctx.a/math.sqrt(1-ctx.es*math.sin(phi_ts)**2)
            scale_ts = rho/(Nts*math.cos(phi_ts)) if math.cos(phi_ts)!=0 else 1.0
            # scale_ts includes centre pole scale factor? At pole area local scale of base method is sc_pole=1 as computed.
            if scale_ts:
                ctx._stere_corr = ctx._stere_corr/scale_ts
def stere_fwd2(ctx, lam, phi):
    if ctx.es:
        chi = conf_lat(phi, ctx.e, ctx.es); chi1 = conf_lat(ctx.lat0, ctx.e, ctx.es)
        sp1, cp1 = math.sin(chi1), math.cos(chi1); sp, cp = math.sin(chi), math.cos(chi)
        denom = 1+sp1*sp+cp1*cp*math.cos(lam)
        if denom <= 1e-15:
            raise FwdError()
        fac = 2*ctx.k0*ctx._stere_corr/denom
        return (ctx.a*fac*cp*math.sin(lam), ctx.a*fac*(cp1*sp-sp1*cp*math.cos(lam)))
    return azi_sph_fwd(ctx, lam, phi, 'stere')
register('stere', stere_fwd2, None, setup=stere_setup2)
register('ups', stere_fwd2, None, setup=stere_setup2)  # setup overridden below for ups defaults in build? placeholder

# ---------- Orthographic ellipsoidal (ECEF tangent plane) ----------
def ortho_fwd2(ctx, lam, phi):
    if ctx.es == 0:
        return azi_sph_fwd(ctx, lam, phi, 'ortho')
    phi1=ctx.lat0
    # visibility: spherical cosc using geodetic (?) PROJ uses that as first check (matches sampled back side)
    cosc = math.sin(phi1)*math.sin(phi)+math.cos(phi1)*math.cos(phi)*math.cos(lam)
    if cosc < 0:
        raise FwdError()
    def ecef(p, l):
        N=ctx.a/math.sqrt(1-ctx.es*math.sin(p)**2)
        return (N*math.cos(p)*math.cos(l), N*math.cos(p)*math.sin(l), N*(1-ctx.es)*math.sin(p))
    P=ecef(phi, lam)
    x = P[1]*ctx.k0
    north = (-math.sin(phi1), 0.0, math.cos(phi1))
    y = (P[0]*north[0] + P[2]*north[2])*ctx.k0
    # y for centre offset: dot(P0,north)=0; good
    return (x, y)
