# ---------- Gnomonic ellipsoidal (central perspective, ECEF) ----------
def gnom_fwd2(ctx, lam, phi):
    if ctx.es == 0:
        return azi_sph_fwd(ctx, lam, phi, 'gnom')
    phi1=ctx.lat0
    cosc = math.sin(phi1)*math.sin(phi)+math.cos(phi1)*math.cos(phi)*math.cos(lam)
    if cosc <= 0:
        raise FwdError()
    def ecef(p,l):
        N=ctx.a/math.sqrt(1-ctx.es*math.sin(p)**2)
        return (N*math.cos(p)*math.cos(l), N*math.cos(p)*math.sin(l), N*(1-ctx.es)*math.sin(p))
    P=ecef(phi,lam); P0=ecef(phi1,0.0)
    n1=(math.cos(phi1),0.0,math.sin(phi1))
    denom=P[0]*n1[0]+P[2]*n1[2]
    if denom<=0: raise FwdError()
    t=(P0[0]*n1[0]+P0[2]*n1[2])/denom
    Q=(P[0]*t,P[1]*t,P[2]*t)
    north=(-math.sin(phi1),0.0,math.cos(phi1))
    x=Q[1]*ctx.k0
    y=((Q[0]-P0[0])*north[0]+(Q[2]-P0[2])*north[2])*ctx.k0
    return (x,y)
register('gnom', gnom_fwd2, None, setup=validate_k)
