a=6378137; es=0.00669438
pts=[(2,48),(10,-30),(0,0),(20,20)]
def orig(proj,extra):
    inp="".join(f"{lon} {lat}\n" for lon,lat in pts).encode()
    out=subprocess.run(["./executable",f"+proj={proj}"]+extra, input=inp, stdout=subprocess.PIPE, stderr=subprocess.PIPE).stdout.decode().strip().splitlines()
    return [(None,None) if '*' in l else tuple(map(float,l.split())) for l in out]
def ecef(phi,lam):
    N=a/math.sqrt(1-es*math.sin(phi)**2); return (N*math.cos(phi)*math.cos(lam), N*math.cos(phi)*math.sin(lam), N*(1-es)*math.sin(phi))
def persp(lam,phi,phi1,h, kind='ecef'):
    if kind=='sph':
        P=(a+h)/a; sp1,cp1=math.sin(phi1),math.cos(phi1); sp,cp=math.sin(phi),math.cos(phi)
        cosc=sp1*sp+cp1*cp*math.cos(lam); g=P-cosc
        if g<=0: return (None,None)
        k=(P-1)/g
        return (a*k*cp*math.sin(lam), a*k*(cp1*sp-sp1*cp*math.cos(lam)))
    P=ecef(phi,lam); P0=ecef(phi1,0)
    n1=(math.cos(phi1),0,math.sin(phi1))  # viewer direction geodetic normal
    V=(P0[0]+h*n1[0], P0[1]+h*n1[1], P0[2]+h*n1[2])
    # intersect ray V->P with plane through P0 normal n1: (Q-P0).n=0, Q=V+t(P-V)
    PV=tuple(P[i]-V[i] for i in range(3))
    denom=sum(PV[i]*n1[i] for i in range(3)); numer=sum((P0[i]-V[i])*n1[i] for i in range(3))
    if denom==0: return (None,None)
