# ---------- Geodetic/cartesian (cart) forward ----------
def cart_fwd(ctx, lam, phi):
    lam_abs = lam + ctx.lon0
    N=ctx.a/math.sqrt(1-ctx.es*math.sin(phi)**2) if ctx.es else ctx.a
    return (N*math.cos(phi)*math.cos(lam_abs)*ctx.k0, N*math.cos(phi)*math.sin(lam_abs)*ctx.k0)
def cart_inv(ctx, x, y):
    # With only x,y available (z=0 in the 2-coordinate interface), longitude from atan2, latitude 0.
    # PROJ's full inverse would use z from a third value, which the proj tool does not pass separately.
    return (math.atan2(y,x)-ctx.lon0, 0.0)
register('cart', cart_fwd, cart_inv)
