# ---------- Transverse Central Cylindrical ----------
def tcc_fwd(ctx, lam, phi):
    sb=math.cos(phi)*math.sin(lam)
    if abs(sb)>=1: raise FwdError()
    x=ctx.a*ctx.k0*sb/math.sqrt(1-sb*sb)
    y=ctx.a*ctx.k0*math.atan2(math.tan(phi), math.cos(lam))
    # centre lat0 shift in transverse longitude: subtract atan2(tan(lat0), cos(0)) = lat0
    y-=ctx.a*ctx.k0*ctx.lat0
    return (x,y)
register('tcc', tcc_fwd, None, sph_only=True, no_inv=True)
# ---------- Transverse Cylindrical Equal Area ----------
def tcea_fwd(ctx, lam, phi):
    x=ctx.a*ctx.k0*math.cos(phi)*math.sin(lam)
    y=ctx.a*ctx.k0*math.atan2(math.tan(phi), math.cos(lam)) - ctx.a*ctx.k0*ctx.lat0
    return (x,y)
register('tcea', tcea_fwd, None, sph_only=True)
# ---------- Kavrayskiy VII ----------
def kav7_fwd(ctx, lam, phi):
    arg=1-3*phi*phi/(math.pi*math.pi)
    if arg<0: arg=0
    return (ctx.a*ctx.k0*(math.sqrt(3)/2)*lam*math.sqrt(arg), ctx.a*ctx.k0*phi)
