# ---------- Sampled separable spherical projections ----------
try:
    from sampled_data import SAMPLED as SAMPLED_PROJS
except Exception:
    SAMPLED_PROJS = {}
def _sampled_interp(vals, ad_deg):
    if ad_deg>=90:
        return vals[-1]
    pos=ad_deg/0.5
    idx=int(pos)
    # cubic Lagrange using 4 points centred where possible
    if idx<=0:
        idxs=[0,1,2,3]; x0=0.0
    elif idx>=len(vals)-2:
        idxs=[len(vals)-4,len(vals)-3,len(vals)-2,len(vals)-1]; x0=idxs[0]*0.5
    else:
        idxs=[idx-1,idx,idx+1,idx+2]; x0=idxs[0]*0.5
    def lag(comp):
        res=0.0
        for ii in idxs:
            xi=ii*0.5; yi=vals[ii][comp]; term=yi
            for jj in idxs:
                if ii!=jj:
                    term*=(ad_deg-jj*0.5)/(xi-jj*0.5)
            res+=term
        return res
    return (lag(0), lag(1))
def _make_sampled(name):
    def fwd(ctx, lam, phi):
        vals=SAMPLED_PROJS[name]
        X,Y=_sampled_interp(vals, abs(math.degrees(phi)))
        y=ctx.a*ctx.k0*Y*(1 if phi>=0 else -1)
        return (ctx.a*ctx.k0*lam*X, y)
    return fwd
