# ---------- Rectangular Polyconic (default lat_ts form) ----------
def rpoly_fwd(ctx, lam, phi):
    if abs(phi) < 1e-12:
        return (ctx.a*ctx.k0*lam, ctx.a*ctx.k0*(phi-ctx.lat0))
    E=lam*math.sin(phi)
    x=ctx.a*ctx.k0*math.sin(E)/math.sin(phi)
    y=ctx.a*ctx.k0*((phi-ctx.lat0)+(1-math.cos(E))/math.tan(phi))
    return (x,y)
