# ---------- Minimal WKT (WKT1/WKT2) projected CRS support ----------
WKT_METHODS={
 'transversemercator':'tmerc','mercator':'merc','mercatorvarianta':'merc','mercatorvariantb':'merc','popularvisualisationpseudomercator':'webmerc','pseudomercator':'webmerc','webmercator':'webmerc',
 'lambertconicconformal2sp':'lcc','lambertconformalconic2sp':'lcc','lambertconicconformal':'lcc','lambertconformalconic':'lcc','lambertconicconformal1sp':'lcc',
 'lambertazimuthalequalarea':'laea','azimuthalequidistant':'aeqd','stereographic':'stere','obliquestereographic':'sterea','orthographic':'ortho','gnomonic':'gnom',
 'equirectangular':'eqc','cylindricalequalarea':'cea','sinusoidal':'sinu','mollweide':'moll','robinson':'robin','universalpolarstereographic':'ups','polarstereographic':'stere',
 'albersequalarea':'aea','albersconicequalarea':'aea','bonne':'bonne','cassinisoldner':'cass','cassini':'cass','polyconic':'poly','eckertiv':'eck4','sinusoidal':'sinu','naturalearth':'natearth','winkel tripel':'wintri'
}
def _wkt_norm(s):
    return ''.join(ch for ch in s.lower() if ch.isalnum())
def parse_wkt_projected(s):
    # ellipsoid
    params_pairs=[]
    m=re.search(r'(?:SPHEROID|ELLIPSOID)\s*\[\s*"[^"]*"\s*,\s*([0-9.eE+-]+)\s*,\s*([0-9.eE+-]+)', s)
    ell_pairs=[]
    if m:
        a_val=m.group(1); rf_val=m.group(2)
        ell_pairs=[('a',a_val), ('rf',rf_val)] if float(rf_val)!=0 else [('a',a_val),('b',a_val)]
    # method
    mm=re.search(r'(?:PROJECTION|METHOD)\s*\[\s*"([^"]+)"', s)
    if not mm:
        return None
    method_norm=_wkt_norm(mm.group(1))
    proj=WKT_METHODS.get(method_norm)
    if proj is None:
        # strip parenthetical etc
        for k,v in WKT_METHODS.items():
            if k in method_norm:
                proj=v; break
    if proj is None:
        return None
    params_pairs.append(('proj',proj))
    # parameters
    param_map={
     'latitudeoforigin':'lat_0','latitudeofnaturalorigin':'lat_0','latitudeoftheorigin':'lat_0','centrelatitude':'lat_0','latitudeofcenter':'lat_0','latitudeofcentre':'lat_0','latitudeofprojectioncentre':'lat_0',
     'longitudeoforigin':'lon_0','longitudeofnaturalorigin':'lon_0','longitudeoftheorigin':'lon_0','centrelongitude':'lon_0','longitudeofcenter':'lon_0','longitudeofcentre':'lon_0','longitudeofprojectioncentre':'lon_0','centralmeridian':'lon_0',
     'scalefactor':'k_0','scalefactoratnaturarorigin':'k_0','scalefactoratnaturalorigin':'k_0','scalefactoratprojectioncentre':'k_0','scalefactoratcenter':'k_0','scalefactoratcentre':'k_0',
     'falseeasting':'x_0','eastingatfalseorigin':'x_0','falseorigin easting':'x_0',
     'falsenorthing':'y_0','northingatfalseorigin':'y_0',
     'latitudeof1ststandardparallel':'lat_1','latitudeoffirststandardparallel':'lat_1','latitudeofstandardparallel1':'lat_1',
     'latitudeof2ndstandardparallel':'lat_2','latitudeofsecondstandardparallel':'lat_2','latitudeofstandardparallel2':'lat_2',
     'latitudeofstandardparallel':'lat_ts','latitudeofpseudo standardparallel':'lat_ts',
     'azimuthofinitialline':'alpha','azimuthatcenteline':'alpha','azimuthatcentreline':'alpha',
     'longitudeofprojectioncentreforcentreline':'lonc','longitudofcentreline':'lonc',
    }
    for pm in re.finditer(r'PARAMETER\s*\[\s*"([^"]+)"\s*,\s*([0-9.eE+-]+)', s):
        pname=_wkt_norm(pm.group(1)); val=pm.group(2)
        key=param_map.get(pname)
        if key:
            params_pairs.append((key,val))
    # projected unit: last UNIT after CONVERSION/PROJECTION in WKT1, or UNIT in final CS in WKT2
    unit_factor=1.0
    # try UNIT["...", factor] occurrences that are not degree/angle
    units=re.findall(r'UNIT\s*\[\s*"([^"]+)"\s*,\s*([0-9.eE+-]+)', s, flags=re.IGNORECASE)
    for uname, ufac in units:
        if 'degree' in uname.lower() or 'radian' in uname.lower() or 'angle' in uname.lower() or 'grad' in uname.lower():
            continue
        try: unit_factor=float(ufac)
        except: pass
    if unit_factor!=1.0:
        # adjust false easting/northing from CRS units to metres for our internal store,
        # and set output unit conversion
        adj=[]
        for k,v in params_pairs:
            if k in ('x_0','y_0'):
                try: adj.append((k, repr(float(v)*unit_factor)))
                except: adj.append((k,v))
            else: adj.append((k,v))
        params_pairs=adj
        params_pairs.append(('to_meter', repr(unit_factor)))
    params_pairs.extend(ell_pairs)
    prm=Params(params_pairs)
    # axis order from WKT2 final CS
    swap=False
    cs_pos=s.rfind('CS[')
    if cs_pos>=0:
        axes=re.findall(r'AXIS\s*\[\s*"([^"]+)"', s[cs_pos:], flags=re.IGNORECASE)
        if len(axes)>=2:
            first=axes[0].lower(); second=axes[1].lower()
            if ('north' in first or first.startswith('y')) and ('east' in second or second.startswith('x')):
                swap=True
    if swap:
        # build as pipeline with axisswap
        toks=["+proj=pipeline","+step"]
        for k,v in params_pairs:
            toks.append(f"+{k}={v}" if v is not None else f"+{k}")
        toks += ["+step","+proj=axisswap","+order=2,1"]
        pipe=build_pipeline(toks); pipe.source='crs'
        return pipe
    return build_operation(prm, [], 'crs')
